        :type n: int
        :rtype: bool
        """
        if n <= 0:
            return False
        while n % 2 == 0:
            n /= 2
        if n == 1:
            return True
        return False

class Solution(object):
    def isAnagram(self, s, t):
        """
        :type s: str
        :type t: str
        :rtype: bool
        """
        if len(s) != len(t):
            return False
        t = list(t)
        for x in s:
            if x in t:
                t.remove(x)
            else:
                return False
        return True

class Solution(object):
    def addDigits(self, num):
        """
        :type num: int
        :rtype: int
        """
        if num<10:
            return num
        digits = [int(x) for x in str(num)]
        count = 0
        while True:
            count += 1
            num  = sum(digits)
            if num < 10:
                return num
            digits = [int(x) for x in str(num)]

class Solution(object):
    def isUgly(self, n):
        """
        :type n: int
        :rtype: bool
        """
        if n <= 0 :
            return False
        if n == 1:
            return True
        while n%2 == 0:
            n /=2
        while n%3 == 0:
            n /=3
        while n%5 == 0:
            n /=5
        if n == 1:
            return True
        return False

class Solution {
    public int numIdenticalPairs(int[] nums) {
        int len = nums.length;
        int res = 0;
        for (int i = 0; i < len - 1; i++) {
            for (int j = i + 1; j < len; j++) {
                if (nums[i] == nums[j]) {
                    res++;
                }
            }
        }
        return res;
    }
}

class Solution {
    public int numWaterBottles(int numBottles, int numExchange) {
        return numBottles + (numBottles - 1) / (numExchange - 1);
    }
}

