 class Solution {
    public int numWaterBottles(int numBottles, int numExchange) {
        int res = numBottles;
        while (numBottles >= numExchange) {
            int resto = numBottles % numExchange;
            numBottles -= resto;
            numBottles /= numExchange;
            res += numBottles;
            numBottles += resto;
        }
        return res;
    }
}
